-- Generated by db/scripts/build_hosted_advisories.py; review before running.
-- Target: audited six-table Supabase legacy schema. NOT an Alembic baseline.
-- New credentials are configured separately; roles start NOLOGIN.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

DO $$ BEGIN
            IF current_user <> 'postgres' THEN
                RAISE EXCEPTION 'Run as the audited postgres database owner';
            END IF;
            IF EXISTS (SELECT FROM pg_roles WHERE rolname IN
                ('safetrip_reader','safetrip_writer','safetrip_migrator'))
                OR EXISTS (SELECT FROM pg_namespace WHERE nspname='advisory')
                OR to_regclass('public.pipeline_runs') IS NOT NULL
                OR to_regclass('public.raw_feeds') IS NOT NULL
                OR to_regclass('public.advisory_summaries') IS NOT NULL
                OR to_regclass('public.alembic_version') IS NOT NULL THEN
                RAISE EXCEPTION 'Unexpected existing foundation; stop and re-audit, do not rerun';
            END IF;
            IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
                WHERE n.nspname='public' AND c.relname IN
                ('countries','culture','scores','bert_scores','clustering','travel_advisories')
                AND c.relkind='r' AND c.relrowsecurity) <> 6 THEN
                RAISE EXCEPTION 'Expected six existing application tables with RLS';
            END IF;
        END $$;
        CREATE ROLE safetrip_reader NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
        CREATE ROLE safetrip_writer NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
        GRANT USAGE ON SCHEMA public TO safetrip_reader, safetrip_writer;
        DO $$ BEGIN
            EXECUTE format('GRANT CONNECT ON DATABASE %I TO safetrip_reader, safetrip_writer', current_database());
        END $$;
        GRANT SELECT ON public.countries TO safetrip_writer;
        CREATE POLICY advisory_writer_country_read ON public.countries
            FOR SELECT TO safetrip_writer USING (true);
        GRANT SELECT ON public.countries, public.culture, public.scores TO safetrip_reader;
        CREATE POLICY advisory_reader_countries ON public.countries FOR SELECT TO safetrip_reader USING (true);
        CREATE POLICY advisory_reader_culture ON public.culture FOR SELECT TO safetrip_reader USING (true);
        CREATE POLICY advisory_reader_scores ON public.scores FOR SELECT TO safetrip_reader USING (true);
        -- XKX is the application's Kosovo join key, also used by the source adapters.
        INSERT INTO public.countries(iso3,name,iso2,continent)
            VALUES ('XKX','Kosovo','XK','Europe') ON CONFLICT (iso3) DO NOTHING;

CREATE TABLE public.pipeline_runs (
            run_id uuid PRIMARY KEY,
            command text NOT NULL,
            status text NOT NULL CHECK (status IN ('running', 'succeeded', 'failed')),
            started_at timestamptz NOT NULL DEFAULT now(),
            finished_at timestamptz,
            metadata jsonb NOT NULL DEFAULT '{}',
            input_sha256 text,
            input_payload jsonb,
            coverage jsonb,
            published_rows integer NOT NULL DEFAULT 0,
            error_type text,
            CHECK ((status = 'running') = (finished_at IS NULL))
        );

CREATE INDEX pipeline_runs_started_at_idx ON public.pipeline_runs(started_at DESC);
        ALTER TABLE public.pipeline_runs ENABLE ROW LEVEL SECURITY;
        GRANT SELECT,INSERT,UPDATE ON public.pipeline_runs TO safetrip_writer;
        CREATE POLICY worker_runs ON public.pipeline_runs TO safetrip_writer USING (true) WITH CHECK (true);

CREATE TABLE public.raw_feeds (
            run_id uuid PRIMARY KEY REFERENCES public.pipeline_runs(run_id),
            fetched_at timestamptz NOT NULL DEFAULT clock_timestamp(),
            sha256 text NOT NULL,
            content bytea NOT NULL
        );
        ALTER TABLE public.raw_feeds ENABLE ROW LEVEL SECURITY;
        REVOKE ALL ON public.raw_feeds FROM PUBLIC, safetrip_reader, safetrip_writer;
        GRANT SELECT, INSERT ON public.raw_feeds TO safetrip_writer;
        CREATE POLICY raw_read ON public.raw_feeds FOR SELECT TO safetrip_writer USING (true);
        CREATE POLICY raw_insert ON public.raw_feeds FOR INSERT TO safetrip_writer WITH CHECK (true);

CREATE SCHEMA advisory;
        REVOKE ALL ON SCHEMA advisory FROM PUBLIC, safetrip_reader, safetrip_writer;
        GRANT USAGE ON SCHEMA advisory TO safetrip_writer;
        ALTER DEFAULT PRIVILEGES IN SCHEMA advisory REVOKE ALL ON TABLES FROM PUBLIC;
        ALTER DEFAULT PRIVILEGES IN SCHEMA advisory REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

        CREATE TABLE advisory.documents (
            document_id uuid PRIMARY KEY,
            source text NOT NULL CHECK (source IN ('us_state', 'uk_fcdo')),
            source_key text NOT NULL CHECK (length(btrim(source_key)) > 0),
            created_at timestamptz NOT NULL DEFAULT now(),
            UNIQUE (source, source_key),
            UNIQUE (document_id, source)
        );

        CREATE TABLE advisory.versions (
            version_id uuid PRIMARY KEY,
            document_id uuid NOT NULL,
            source text NOT NULL,
            parser_version text NOT NULL CHECK (length(btrim(parser_version)) > 0),
            content_sha256 text NOT NULL CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
            raw_payload bytea NOT NULL CHECK (octet_length(raw_payload) > 0),
            source_url text NOT NULL CHECK (source_url ~ '^https://'),
            source_public_updated_at timestamptz,
            source_updated_at timestamptz,
            source_reviewed_at timestamptz,
            us_level smallint,
            uk_alert_status text[],
            metadata jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(metadata) = 'object'),
            created_at timestamptz NOT NULL DEFAULT now(),
            FOREIGN KEY (document_id, source) REFERENCES advisory.documents(document_id, source),
            UNIQUE (document_id, content_sha256, parser_version),
            UNIQUE (version_id, document_id),
            CHECK (content_sha256 = encode(sha256(raw_payload), 'hex')),
            CHECK (
                (source = 'us_state' AND us_level IS NOT NULL AND us_level BETWEEN 1 AND 4
                    AND uk_alert_status IS NULL)
                OR
                (source = 'uk_fcdo' AND us_level IS NULL AND uk_alert_status IS NOT NULL
                    AND array_position(uk_alert_status, NULL) IS NULL
                    AND uk_alert_status <@ ARRAY[
                        'avoid_all_travel_to_whole_country',
                        'avoid_all_but_essential_travel_to_whole_country',
                        'avoid_all_travel_to_parts',
                        'avoid_all_but_essential_travel_to_parts'
                    ]::text[])
            )
        );

        -- Document coverage is distinct from the geographic scope of a warning.
        CREATE TABLE advisory.coverage (
            coverage_id uuid PRIMARY KEY,
            version_id uuid NOT NULL REFERENCES advisory.versions(version_id),
            iso3 text REFERENCES public.countries(iso3),
            scope text NOT NULL CHECK (scope IN ('whole_country', 'parts', 'unresolved')),
            region_label text,
            CHECK (
                (scope = 'whole_country' AND iso3 IS NOT NULL AND region_label IS NULL)
                OR (scope = 'parts' AND iso3 IS NOT NULL AND length(btrim(region_label)) > 0)
                OR (scope = 'unresolved' AND length(btrim(region_label)) > 0)
            ),
            CHECK (scope = 'whole_country' OR region_label IS NOT NULL)
        );
        CREATE UNIQUE INDEX advisory_coverage_unique ON advisory.coverage
            (version_id, coalesce(iso3, ''), scope, coalesce(region_label, ''));
        CREATE INDEX advisory_coverage_country ON advisory.coverage (iso3);

        -- Seeing identical content again records freshness without duplicating a version.
        CREATE TABLE advisory.observations (
            run_id uuid NOT NULL REFERENCES public.pipeline_runs(run_id),
            document_id uuid NOT NULL REFERENCES advisory.documents(document_id),
            version_id uuid NOT NULL,
            fetched_at timestamptz NOT NULL,
            PRIMARY KEY (run_id, document_id),
            FOREIGN KEY (version_id, document_id) REFERENCES advisory.versions(version_id, document_id)
        );
        CREATE INDEX advisory_observations_freshness ON advisory.observations
            (document_id, fetched_at DESC);

        CREATE TABLE advisory.paragraphs (
            version_id uuid NOT NULL REFERENCES advisory.versions(version_id),
            section_slug text NOT NULL CHECK (length(btrim(section_slug)) > 0),
            paragraph_index integer NOT NULL CHECK (paragraph_index >= 0),
            section_title text NOT NULL,
            heading text,
            body text NOT NULL CHECK (length(btrim(body)) > 0),
            PRIMARY KEY (version_id, section_slug, paragraph_index)
        );

        -- Experimental outputs have no permission or path into public scores.
        CREATE TABLE advisory.analyses (
            analysis_id uuid PRIMARY KEY,
            version_id uuid NOT NULL REFERENCES advisory.versions(version_id),
            run_id uuid NOT NULL REFERENCES public.pipeline_runs(run_id),
            analyzer_version text NOT NULL CHECK (length(btrim(analyzer_version)) > 0),
            input_sha256 text NOT NULL CHECK (input_sha256 ~ '^[0-9a-f]{64}$'),
            metadata jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(metadata) = 'object'),
            created_at timestamptz NOT NULL DEFAULT now(),
            UNIQUE (version_id, analyzer_version, input_sha256),
            UNIQUE (analysis_id, version_id)
        );
        CREATE TABLE advisory.evidence (
            analysis_id uuid NOT NULL,
            version_id uuid NOT NULL,
            section_slug text NOT NULL,
            paragraph_index integer NOT NULL,
            category text NOT NULL CHECK (category IN (
                'crime', 'kidnapping', 'terrorism', 'conflict_unrest', 'health',
                'natural_hazards', 'transport', 'legal_restrictions'
            )),
            context text NOT NULL DEFAULT 'unreviewed' CHECK (context IN (
                'unreviewed', 'destination_specific', 'generic', 'historical', 'third_region', 'negated'
            )),
            PRIMARY KEY (analysis_id, section_slug, paragraph_index, category),
            FOREIGN KEY (analysis_id, version_id) REFERENCES advisory.analyses(analysis_id, version_id),
            FOREIGN KEY (version_id, section_slug, paragraph_index)
                REFERENCES advisory.paragraphs(version_id, section_slug, paragraph_index)
        );
ALTER TABLE advisory.documents ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON advisory.documents FROM PUBLIC, safetrip_reader, safetrip_writer;
GRANT SELECT, INSERT ON advisory.documents TO safetrip_writer;
CREATE POLICY worker_read ON advisory.documents FOR SELECT TO safetrip_writer USING (true);
CREATE POLICY worker_insert ON advisory.documents FOR INSERT TO safetrip_writer WITH CHECK (true);
ALTER TABLE advisory.versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON advisory.versions FROM PUBLIC, safetrip_reader, safetrip_writer;
GRANT SELECT, INSERT ON advisory.versions TO safetrip_writer;
CREATE POLICY worker_read ON advisory.versions FOR SELECT TO safetrip_writer USING (true);
CREATE POLICY worker_insert ON advisory.versions FOR INSERT TO safetrip_writer WITH CHECK (true);
ALTER TABLE advisory.coverage ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON advisory.coverage FROM PUBLIC, safetrip_reader, safetrip_writer;
GRANT SELECT, INSERT ON advisory.coverage TO safetrip_writer;
CREATE POLICY worker_read ON advisory.coverage FOR SELECT TO safetrip_writer USING (true);
CREATE POLICY worker_insert ON advisory.coverage FOR INSERT TO safetrip_writer WITH CHECK (true);
ALTER TABLE advisory.observations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON advisory.observations FROM PUBLIC, safetrip_reader, safetrip_writer;
GRANT SELECT, INSERT ON advisory.observations TO safetrip_writer;
CREATE POLICY worker_read ON advisory.observations FOR SELECT TO safetrip_writer USING (true);
CREATE POLICY worker_insert ON advisory.observations FOR INSERT TO safetrip_writer WITH CHECK (true);
ALTER TABLE advisory.paragraphs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON advisory.paragraphs FROM PUBLIC, safetrip_reader, safetrip_writer;
GRANT SELECT, INSERT ON advisory.paragraphs TO safetrip_writer;
CREATE POLICY worker_read ON advisory.paragraphs FOR SELECT TO safetrip_writer USING (true);
CREATE POLICY worker_insert ON advisory.paragraphs FOR INSERT TO safetrip_writer WITH CHECK (true);
ALTER TABLE advisory.analyses ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON advisory.analyses FROM PUBLIC, safetrip_reader, safetrip_writer;
GRANT SELECT, INSERT ON advisory.analyses TO safetrip_writer;
CREATE POLICY worker_read ON advisory.analyses FOR SELECT TO safetrip_writer USING (true);
CREATE POLICY worker_insert ON advisory.analyses FOR INSERT TO safetrip_writer WITH CHECK (true);
ALTER TABLE advisory.evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON advisory.evidence FROM PUBLIC, safetrip_reader, safetrip_writer;
GRANT SELECT, INSERT ON advisory.evidence TO safetrip_writer;
CREATE POLICY worker_read ON advisory.evidence FOR SELECT TO safetrip_writer USING (true);
CREATE POLICY worker_insert ON advisory.evidence FOR INSERT TO safetrip_writer WITH CHECK (true);

CREATE VIEW public.advisory_summaries AS
        WITH latest AS (
            SELECT DISTINCT ON (o.document_id) o.document_id, o.version_id, o.fetched_at
            FROM advisory.observations o
            JOIN public.pipeline_runs r ON r.run_id = o.run_id
            JOIN advisory.versions v ON v.version_id = o.version_id
            WHERE r.status = 'succeeded'
            ORDER BY o.document_id, o.fetched_at DESC, v.created_at DESC,
                     r.finished_at DESC, o.version_id
        )
        SELECT c.iso3, d.document_id, d.source, v.version_id,
               v.source_url, v.source_public_updated_at, v.source_updated_at,
               v.source_reviewed_at, l.fetched_at, v.us_level, v.uk_alert_status,
               c.scope AS coverage_scope, c.region_label
        FROM latest l
        JOIN advisory.documents d ON d.document_id = l.document_id
        JOIN advisory.versions v ON v.version_id = l.version_id
        JOIN advisory.coverage c ON c.version_id = v.version_id
        WHERE c.iso3 IS NOT NULL AND c.scope <> 'unresolved';
        REVOKE ALL ON public.advisory_summaries FROM PUBLIC, safetrip_writer, safetrip_reader;
        GRANT SELECT ON public.advisory_summaries TO safetrip_reader;

-- Supabase may give API roles default privileges on newly created public objects.
        REVOKE ALL ON public.pipeline_runs, public.raw_feeds, public.advisory_summaries
            FROM PUBLIC, anon, authenticated, service_role;
        REVOKE ALL ON SCHEMA advisory FROM PUBLIC, anon, authenticated, service_role, safetrip_reader;
        REVOKE ALL ON ALL TABLES IN SCHEMA advisory FROM PUBLIC, anon, authenticated, service_role;
        -- Fail closed if inherited or default grants undermine this installation.
        DO $$ DECLARE r text; t text; p text; BEGIN
            FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
                FOREACH t IN ARRAY ARRAY['public.pipeline_runs','public.raw_feeds','public.advisory_summaries'] LOOP
                    FOREACH p IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] LOOP
                        IF has_table_privilege(r,t,p) THEN
                            RAISE EXCEPTION 'Unexpected API access to new relation: % % %', r,t,p;
                        END IF;
                    END LOOP;
                END LOOP;
                IF has_schema_privilege(r,'advisory','USAGE') OR has_schema_privilege(r,'advisory','CREATE') THEN
                    RAISE EXCEPTION 'Unexpected API access to private schema: %', r;
                END IF;
            END LOOP;
            FOREACH r IN ARRAY ARRAY['safetrip_reader','safetrip_writer'] LOOP
                IF has_schema_privilege(r,'public','CREATE') THEN
                    RAISE EXCEPTION 'Application role can create public objects: %', r;
                END IF;
                FOREACH t IN ARRAY ARRAY['public.scores','public.clustering','public.bert_scores','public.travel_advisories','public.countries','public.culture'] LOOP
                    FOREACH p IN ARRAY ARRAY['INSERT','UPDATE','DELETE','TRUNCATE'] LOOP
                        IF has_table_privilege(r,t,p) THEN
                            RAISE EXCEPTION 'Application role has unexpected legacy write access: % %',r,t;
                        END IF;
                    END LOOP;
                END LOOP;
            END LOOP;
        END $$;
        COMMIT;
